+# Native 1.15 Caesaropapism restored as a separate definition.
+law_caesaropapism = {
+	group = lawgroup_church_and_state
+	parent = law_state_religion # Inherits ideological stances from parent
+
+	icon = "gfx/interface/icons/law_icons/caesaropapism.dds"
+
+	progressiveness = -50
+
+	is_visible = {
+		OR = {
+			c:RUS ?= this
+			AND = {
+				exists = c:RUS
+				is_subject_of = c:RUS
+				country_is_subject_type_valid_for_caesaropapism = yes
+			}
+		}
+		NOT = {
+			has_law_or_variant = law_type:law_theocracy
+		}
+	}
+
+	on_activate = {
+		if = {
+			limit = {
+				has_modifier = antireligious_policies
+			}
+			remove_modifier = antireligious_policies
+		}
+		recalculate_pop_ig_support = yes
+	}
+
+	modifier = {
+		interest_group_ig_devout_pol_str_mult = 0.15
+		country_bureaucrats_pol_str_mult = 0.5
+		country_authority_add = 200
+		country_state_religion_wages_mult = 0.1
+		country_non_state_religion_wages_mult = -0.1
+
+		country_acceptance_state_religion_add = 25
+		country_acceptance_shared_religious_trait_add = 0
+		country_acceptance_shared_religious_trait_group_add = -10
+		country_acceptance_no_shared_religious_trait_add = -25
+
+		country_allow_conversion_violent_hostility_bool = yes
+		country_allow_conversion_cultural_erasure_bool = yes
+		country_allow_conversion_open_prejudice_bool = yes
+		country_allow_conversion_second_rate_citizen_bool = yes
+		country_allow_conversion_full_acceptance_bool = yes
+	}
+
+	can_impose = {
+		OR = {
+			AND = {
+				is_in_same_power_bloc = scope:target_country
+				AND = {
+					modifier:country_can_impose_same_lawgroup_church_and_state_in_power_bloc_bool = yes
+					has_law = scope:law
+				}
+			}
+			can_impose_law_default = yes
+		}
+	}
+
+	ai_will_do = {
+		exists = ruler
+		ruler = {
+			OR = {
+				has_ideology = ideology:ideology_theocrat
+				has_ideology = ideology:ideology_traditionalist
+			}
+		}
+	}
+
+	ai_enact_weight_modifier = { #Petitions
+		value = 0
+
+		if = {
+			limit = { ai_has_enact_weight_modifier_journal_entries = yes }
+			add = 750
+		}
+	}
+
+	ai_impose_chance = {
+		value = 0
+
+		if = {
+			limit = {
+				has_law = law_type:law_caesaropapism
+				power_bloc ?= { has_identity = identity:identity_religious }
+				religion = scope:target_country.religion
+			}
+
+			add = base_impose_law_weight
+
+			# Very important for religious blocs
+			if = {
+				limit = { scope:target_country = { has_law_or_variant = law_type:law_freedom_of_conscience } }
+				multiply = 2
+			}
+			else = {
+				multiply = 5
+			}
+		}
+	}
+}

@@ -0,0 +1,90 @@
+# Restore the single native1.15 law hidden by the older scenario file.
+law_internal_colonization = {
+	group = lawgroup_colonization
+
+	icon = "gfx/interface/icons/law_icons/internal_colonization.dds"
+
+	progressiveness = 25
+
+	unlocking_technologies = {
+		colonization
+	}
+
+	can_enact = {
+		OR = {
+			is_country_type = colonial
+			any_scope_state = {
+				is_incorporated = no
+			}
+		}
+	}
+
+	institution = institution_colonial_affairs
+	institution_modifier = {
+		state_colony_growth_creation_factor = -0.1
+		state_assimilation_mult = 0.05
+		state_migration_pull_unincorporated_mult = 0.2
+	}
+
+	can_impose = {
+		OR = {
+			AND = {
+				is_in_same_power_bloc = scope:target_country
+				AND = {
+					modifier:country_can_impose_same_lawgroup_colonization_in_power_bloc_bool = yes
+					has_law = scope:law
+				}
+			}
+			can_impose_law_default = yes
+		}
+	}
+
+	ai_will_do = {
+		OR = {
+			has_law_or_variant = law_type:law_colonial_exploitation
+			navy_size >= 50
+			has_journal_entry = je_tp_pool_develop_frontier
+		}
+	}
+
+	ai_enact_weight_modifier = { #Petitions
+		value = 0
+
+		if = {
+			limit = { ai_has_enact_weight_modifier_journal_entries = yes }
+			add = 750
+		}
+	}
+
+	ai_impose_chance = {
+		value = 0
+
+		if = {
+			limit = {
+				OR = {
+					has_law = law_type:law_colonial_resettlement
+					has_law_or_variant = law_type:law_frontier_colonization
+				}
+				scope:target_country = {
+					has_law_or_variant = law_type:law_no_colonial_affairs
+				}
+				power_bloc ?= { has_principle_group = principle_group:principle_group_colonial_offices }
+			}
+			add = 10
+		}
+
+		if = {
+			limit = {
+				scope:target_country = {
+					c:BIC ?= this
+					OR = {
+						has_journal_entry = je_british_dictate_plantations
+						has_journal_entry = je_british_dictate_military
+						has_journal_entry = je_british_dictate_universities
+					}
+				}
+			}
+			multiply = 0
+		}
+	}
+}

