			name = election_event_cooldown
			months = election_event_cooldown_months
		}
		random_interest_group = {
			limit = {
				has_party = yes
				is_in_government = yes
			}
			party = {
				save_scope_as = high_food_price_party
			}
		}
		if = {
			limit = {
				market_capital.market = {
					mg:grain = {
						market_goods_pricier > 0.25
					}
