		else_if = {
			limit = {
				market_capital.market = {
					mg:groceries = {
						market_goods_pricier > 0.25
					}
				}
			}
			g:groceries = {
				save_scope_as = basic_foodstuff
			}
		}
		else_if = {
			limit = {
				market_capital.market = {
					mg:fish = {
						market_goods_pricier > 0.25
					}
				}
			}
			g:fish = {
				save_scope_as = basic_foodstuff
			}
		}
		else_if = {
			limit = {
				market_capital.market = {
					mg:meat = {
						market_goods_pricier > 0.25
					}
				}
			}
			g:meat = {
				save_scope_as = basic_foodstuff
			}
		}
	}

	cancellation_trigger = {
		in_election_campaign = no
